mapper.select:
select estimate_id, from_acode, to_acode, express_company_code, express_type,
       delivery_expend_time, total_time, remain_time, provider_code,
       last_query_time, expire_time, create_time, update_time
from ry_business.ry_rental_express_time_estimate
where from_acode = #{fromAcode}
  and to_acode = #{toAcode}
  and express_company_code = #{expressCompanyCode}
  and provider_code = #{providerCode}
  and expire_time > now()

  and express_type = #{expressType}

order by update_time desc, estimate_id desc
limit 1
